import{parseMatrix,calculate,csv}from'./core.js';import{catalogs}from'./locales.js';
const lang=document.documentElement.lang,t=catalogs[lang]||catalogs.ko,$=id=>document.getElementById(id),nf=new Intl.NumberFormat(lang,{maximumFractionDigits:6}),fmt=x=>nf.format(x);let exported='';
document.title=t.title;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t[e.dataset.t]);$('language').value=lang;$('language').onchange=e=>location.href=new URL(e.target.value==='ko'?'./':e.target.value+'/',document.baseURI).href;
const text=(tag,value,parent)=>{const e=document.createElement(tag);e.textContent=value;parent.append(e);return e;};const status=(s,error=false)=>{$('status').textContent=s;$('status').className=error?'error':'status';};
function table(parent,headers,rows){const wrap=text('div','',parent);wrap.className='table-wrap';const table=text('table','',wrap),head=text('tr','',text('thead','',table));headers.forEach(h=>text('th',h,head));const body=text('tbody','',table);rows.forEach(row=>{const tr=text('tr','',body);row.forEach(v=>text('td',v,tr));});}
function invalidate(){exported='';document.querySelectorAll('[data-export]').forEach(b=>b.disabled=true);$('results').replaceChildren();text('p',t.empty,$('results'));status(t.empty);}
function make(){try{const model=parseMatrix($('criteria').value,$('options').value),r=calculate(model);$('results').replaceChildren();const metrics=text('div','',$('results'));metrics.className='metrics';[[t.optionCount,r.rows.length],[t.criterionCount,r.criteria.length],[t.leaders,r.rows.filter(x=>x.rank===1).map(x=>x.name).join(' · ')]].forEach(([k,v])=>{const box=text('div','',metrics);text('span',k,box);text('strong',v,box);});const headers=[t.alternative,t.baseScore,t.scenarioScore,t.baseRank,t.scenarioRank,t.rankChange];table($('results'),headers,r.rows.map(o=>[o.name,fmt(o.total),fmt(o.scenarioTotal),o.rank,o.scenarioRank,(o.rank-o.scenarioRank>0?'+':'')+(o.rank-o.scenarioRank)]));text('p',t.tie,$('results')).className='hint';
 const weightTitle=text('h3',t.criteria,$('results'));table($('results'),[t.criterion,t.baseWeight,t.scenarioWeight],r.criteria.map(c=>[c.name,fmt(c.share*100)+'%',fmt(c.scenarioShare*100)+'%']));
 const details=text('details','',$('results'));text('summary',t.evidence,details);r.rows.forEach(o=>{text('h3',o.name,details);table(details,[t.criterion,t.options,t.contribution,t.scenarioContribution],r.criteria.map((c,i)=>[c.name,fmt(o.scores[i]),fmt(o.contributions[i]),fmt(o.scenarioContributions[i])]));});
 exported=csv(r.rows.map(o=>[o.name,o.total,o.scenarioTotal,o.rank,o.scenarioRank,o.rank-o.scenarioRank,...o.scores,...o.contributions,...o.scenarioContributions]),[...headers,...r.criteria.map(c=>c.name+' · '+t.options),...r.criteria.map(c=>c.name+' · '+t.contribution),...r.criteria.map(c=>c.name+' · '+t.scenarioContribution)]);document.querySelectorAll('[data-export]').forEach(b=>b.disabled=false);status(t.ready);
 }catch(e){invalidate();status((t[e.code]||t.limit)+(e.detail?' '+e.detail:''),true);}}
$('build').onclick=make;$('example').onclick=()=>{$('criteria').value=`${t.sampleA} | 5 | 2\n${t.sampleB} | 3 | 6\n${t.sampleC} | 2 | 2`;$('options').value=`${t.sampleX} | 90 | 50 | 70\n${t.sampleY} | 65 | 95 | 60\n${t.sampleZ} | 75 | 75 | 80`;make();};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([exported],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='decision-matrix.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(exported);status(t.copied);}catch{status(t.copyFail,true);}};['criteria','options'].forEach(id=>$(id).addEventListener('input',invalidate));$('example').click();
